 #include <KIO/ApplicationLauncherJob>
 #include <KLocalizedString>
 #include <KNotificationJobUiDelegate>
@@ -205,6 +206,20 @@ QString storageIdFromService(KService::Ptr service)
     return storageId;
 }

+QString launchShortcut(const KService::Ptr &service)
+{
+    if (!service) {
+        return {};
+    }
+
+    const QList<QKeySequence> shortcuts = KGlobalAccel::self()->globalShortcut(service->storageId(), QStringLiteral("_launch"));
+    if (shortcuts.isEmpty()) {
+        return {};
+    }
+
+    return shortcuts.first().toString(QKeySequence::NativeText);
+}
